+    }
+
+    @TaskAction
+    public void executeTask() throws IOException {
+        if (addVersion == null && removeVersion == null) {
+            throw new IllegalArgumentException("No versions to add or remove specified");
+        }
+        if (setCurrent && addVersion == null) {
