+            }
+        }
+        if (removeVersion != null) {
+            LOGGER.lifecycle("Removing version [{}] from [{}]", removeVersion, versionJava);
+            var removed = removeVersionConstant(modifiedFile.orElse(file), removeVersion);
+            if (removed.isPresent()) {
